-- ============================================================================
-- PRODUCTION: add the Handover stage questions (HAND-01 to HAND-12)
-- ============================================================================
-- Adds only new rows; existing rows are never overwritten. Safe to run more than once.
-- Run together with the new application code.
-- ============================================================================
BEGIN;
SELECT COUNT(*) AS handover_questions FROM questions WHERE stage = 'Handover' AND "isActive";
COMMIT;
