INSERT INTO questions ("questionKey", stage, position, text, type, mandatory, options, help, "isActive") VALUES ('HAND-01', 'Handover', 1, 'Who are the key customer stakeholders and internal stakeholders involved in the project? Give names, roles, contact details and responsibilities.', 'text', TRUE, NULL, NULL, TRUE) ON CONFLICT ("questionKey") DO NOTHING;
INSERT INTO questions ("questionKey", stage, position, text, type, mandatory, options, help, "isActive") VALUES ('HAND-02', 'Handover', 2, 'What has been agreed that the project team must deliver? Final scope, products, modules, deliverables and exclusions.', 'text', TRUE, NULL, NULL, TRUE) ON CONFLICT ("questionKey") DO NOTHING;
INSERT INTO questions ("questionKey", stage, position, text, type, mandatory, options, help, "isActive") VALUES ('HAND-03', 'Handover', 3, 'What business problem is the customer expecting us to solve, and what does success look like? Expected outcome and acceptance criteria.', 'text', TRUE, NULL, NULL, TRUE) ON CONFLICT ("questionKey") DO NOTHING;
INSERT INTO questions ("questionKey", stage, position, text, type, mandatory, options, help, "isActive") VALUES ('HAND-04', 'Handover', 4, 'What workflows or business processes must the solution support? Current process, expected future process, approval flows and business rules.', 'text', TRUE, NULL, NULL, TRUE) ON CONFLICT ("questionKey") DO NOTHING;
INSERT INTO questions ("questionKey", stage, position, text, type, mandatory, options, help, "isActive") VALUES ('HAND-05', 'Handover', 5, 'What is the expected delivery and implementation timeline? Start date, milestones, target completion date and dependencies.', 'text', TRUE, NULL, NULL, TRUE) ON CONFLICT ("questionKey") DO NOTHING;
INSERT INTO questions ("questionKey", stage, position, text, type, mandatory, options, help, "isActive") VALUES ('HAND-06', 'Handover', 6, 'What availability, uptime, performance or support expectations have been agreed? Service hours, SLA and response expectations, where applicable.', 'text', TRUE, NULL, NULL, TRUE) ON CONFLICT ("questionKey") DO NOTHING;
INSERT INTO questions ("questionKey", stage, position, text, type, mandatory, options, help, "isActive") VALUES ('HAND-07', 'Handover', 7, 'What integrations, data migration, customisation or third-party dependencies are required? Systems involved, data sources, dependency owners and responsibilities.', 'text', TRUE, NULL, NULL, TRUE) ON CONFLICT ("questionKey") DO NOTHING;
INSERT INTO questions ("questionKey", stage, position, text, type, mandatory, options, help, "isActive") VALUES ('HAND-08', 'Handover', 8, 'What customer inputs, access, resources or approvals are required before work can begin? Access arrangements, data, documents, staff availability and approval dependencies.', 'text', TRUE, NULL, NULL, TRUE) ON CONFLICT ("questionKey") DO NOTHING;
INSERT INTO questions ("questionKey", stage, position, text, type, mandatory, options, help, "isActive") VALUES ('HAND-09', 'Handover', 9, 'What are the commercial commitments and payment milestones? Contract value, payment schedule, invoicing milestones and special commitments.', 'text', TRUE, NULL, NULL, TRUE) ON CONFLICT ("questionKey") DO NOTHING;
INSERT INTO questions ("questionKey", stage, position, text, type, mandatory, options, help, "isActive") VALUES ('HAND-10', 'Handover', 10, 'What risks, unresolved issues, assumptions or commitments must the project team know about? Outstanding concerns, promised features, scope boundaries and agreed exceptions.', 'text', TRUE, NULL, NULL, TRUE) ON CONFLICT ("questionKey") DO NOTHING;
INSERT INTO questions ("questionKey", stage, position, text, type, mandatory, options, help, "isActive") VALUES ('HAND-11', 'Handover', 11, 'Who is the project owner on our side, who is the customer project owner, and who is responsible for each next action? Named owners and responsibilities.', 'text', TRUE, NULL, NULL, TRUE) ON CONFLICT ("questionKey") DO NOTHING;
INSERT INTO questions ("questionKey", stage, position, text, type, mandatory, options, help, "isActive") VALUES ('HAND-12', 'Handover', 12, 'When will the handover meeting take place, and have the required documents and records been shared? Handover date, attendees, document checklist and status.', 'text', TRUE, NULL, NULL, TRUE) ON CONFLICT ("questionKey") DO NOTHING;
